"""
Converts a binary file (icon) into a C header with the complete HTTP response:
the header lines followed by the file bytes.

Usage

    python bin2header.py -f icon.png -o icon.png.h -n icon_png --content-type image/png
"""

import argparse


TEMPLATE = """// ---------------------------------------------------------- //
// This file is autogenerated by bin2header.py; do not edit!  //
// ---------------------------------------------------------- //

#ifndef {guard}_H_
#define {guard}_H_

#include <stddef.h>

static const unsigned char {name}[] = {{
{data}
}};
static const size_t {name}_len = {length};

#endif  // {guard}_H_
"""


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("-f", "--file", required=True)
    parser.add_argument("-o", "--output", required=True)
    parser.add_argument("-n", "--name", required=True)
    parser.add_argument("--content-type", required=True)
    parser.add_argument("--cache-seconds", type=int, default=86400)
    args = parser.parse_args()

    with open(args.file, "rb") as fp:
        body = fp.read()
    header = (f"HTTP/1.1 200 OK\r\nContent-Type: {args.content_type}\r\n"
              f"Content-Length: {len(body)}\r\nCache-Control: max-age={args.cache_seconds}\r\n\r\n").encode()
    blob = header + body

    lines = []
    for i in range(0, len(blob), 16):
        lines.append("    " + ", ".join(f"0x{b:02x}" for b in blob[i:i + 16]) + ",")
    with open(args.output, "w") as fp:
        fp.write(TEMPLATE.format(guard=args.name.upper(), name=args.name, data="\n".join(lines), length=len(blob)))


if __name__ == "__main__":
    main()
